// Minimal simulation memory/EEI endpoints, not replacement processor modules.
// Event reference is generated by an independent sequential Python interpreter.
module core_tb;
  import rv32_pkg::*;
  `include "build/core-vectors/config.svh"
  logic clk=0, rst=1;
  logic iqv,iqr,irv,irr,dqv,dqr,drv,drr,tv,tr,rv,rr;
  word_t ia,rpc;
  if_response_t ir;
  mem_request_t dq;
  mem_response_t dr;
  retire_bundle_t retired;
  trap_t trap;
  core dut (.clk_i(clk),.rst_i(rst),.reset_pc_i(32'b0),
    .instruction_request_valid_o(iqv),.instruction_request_address_o(ia),.instruction_request_ready_i(iqr),
    .instruction_response_valid_i(irv),.instruction_response_i(ir),.instruction_response_ready_o(irr),
    .data_request_valid_o(dqv),.data_request_o(dq),.data_request_ready_i(dqr),
    .data_response_valid_i(drv),.data_response_i(dr),.data_response_ready_o(drr),
    .retire_o(retired),.trap_valid_o(tv),.trap_o(trap),.trap_ready_i(tr),
    .resume_valid_i(rv),.resume_pc_i(rpc),.resume_ready_o(rr));
  word_t imem [0:PROGRAM_WORDS-1];
  byte unsigned mem [0:4095], expected_mem [0:4095];
  integer fd, fields, events=0, cycles=0, seed=1;
  integer iw=-1,dw=-1;
  word_t expected [0:11];
  logic resume_pending=0;
  word_t saved_resume=0;
  logic if_hold=0,data_hold=0,trap_hold=0;
  word_t held_ia;
  mem_request_t held_dq;
  trap_t held_trap;
  integer wide=0, stalls=0, packet_stalls=0, stale_redirects=0;
  logic held_packet_valid [7];
  packet_t held_packet [7];
  task automatic next_expected;
    fields=$fscanf(fd,"%h %h %h %h %h %h %h %h %h %h %h %h\n",
      expected[0],expected[1],expected[2],expected[3],expected[4],expected[5],
      expected[6],expected[7],expected[8],expected[9],expected[10],expected[11]);
    if (fields!=12) $fatal(1,"Missing expected event %0d",events);
    events++;
  endtask
  task automatic tick;
    #5; clk=1; #5; clk=0;
  endtask
  initial begin
    if ($value$plusargs("seed=%d",seed)) begin end
    $readmemh("build/core-vectors/program.hex",imem);
    $readmemh("build/core-vectors/memory.hex",expected_mem);
    foreach (mem[i]) mem[i]=0;
    fd=$fopen("build/core-vectors/expected.txt","r");
    if (fd==0) $fatal(1,"Cannot read reference events");
    iqr=0;irv=0;ir='0;dqr=0;drv=0;dr='0;tr=0;rv=0;rpc=0;
    foreach (held_packet_valid[i]) held_packet_valid[i]=0;
    tick(); tick(); rst=0;
    while (cycles<40000) begin
      // Inputs change only at falling-edge boundaries; check before rising edge.
      iqr=iw<0 && (cycles+seed)%5!=0;
      dqr=dw<0 && (cycles+seed)%4!=0;
      irv=iw==0; drv=dw==0;
      tr=(cycles+seed)%7==0;
      rv=resume_pending && (cycles+seed)%3==0;
      rpc=saved_resume;
      #1;
      for (int stage=0;stage<7;stage++) begin
        if (held_packet_valid[stage] && !(stage<4 ? dut.front_flush : dut.back_flush) &&
            (!dut.valid[stage] || dut.packets[stage]!=held_packet[stage]))
          $fatal(1,"Unstable pipeline packet stage=%0d",stage);
        held_packet_valid[stage]=dut.valid[stage]&&!dut.ready[stage];
        held_packet[stage]=dut.packets[stage];
        if (held_packet_valid[stage]) packet_stalls++;
        if (dut.valid[stage]) for (int lane=1;lane<4;lane++)
          if (dut.packets[stage][lane].valid && !dut.packets[stage][lane-1].valid)
            $fatal(1,"Noncompact packet stage=%0d",stage);
      end
      if (dut.redirect_valid && dut.u_fetch.outstanding_o) stale_redirects++;
      if (dut.busy[0] || dut.u_regfile.regs_q[0]!=0) $fatal(1,"x0 invariant");
      if (if_hold && (!iqv || ia!=held_ia)) $fatal(1,"Unstable IF request");
      if (data_hold && (!dqv || dq!=held_dq)) $fatal(1,"Unstable data request");
      if (trap_hold && (!tv || trap!=held_trap)) $fatal(1,"Unstable trap report");
      if_hold=iqv&&!iqr; held_ia=ia;
      data_hold=dqv&&!dqr; held_dq=dq;
      trap_hold=tv&&!tr; held_trap=trap;
      if (if_hold || data_hold || trap_hold) stalls++;
      if (retired[3].valid) wide++;
      for (int i=0;i<4;i++) if (retired[i].valid) begin
        next_expected();
        if (expected[0]!=0 || retired[i].pc!=expected[1] || retired[i].instruction!=expected[2])
          $fatal(1,"Event %0d PC=%h expected PC=%h type=%0d",events,retired[i].pc,expected[1],expected[0]);
        if (32'(retired[i].writes_rd)!=expected[3] ||
            (retired[i].writes_rd && (32'(retired[i].rd)!=expected[4] || retired[i].value!=expected[5])))
          $fatal(1,"Register mismatch PC=%h rd=%0d value=%h expected=%h",retired[i].pc,retired[i].rd,retired[i].value,expected[5]);
        if (32'(retired[i].memory)!=expected[8]) $fatal(1,"Memory flag mismatch");
        if (retired[i].memory && (retired[i].address!=expected[7] ||
            32'(retired[i].memory_write)!=expected[9] || 32'(retired[i].byte_mask)!=expected[10] ||
            retired[i].memory_data!=expected[11])) $fatal(1,"Memory trace mismatch at %h",retired[i].pc);
      end
      if (tv && tr) begin
        next_expected();
        if (expected[0]!=1 || trap.pc!=expected[1] || trap.instruction!=expected[2] ||
            !trap.fault.valid || 32'(trap.fault.kind)!=expected[6] || trap.fault.address!=expected[7])
          $fatal(1,"Trap mismatch PC=%h expected=%h cause=%0d expected=%0d address=%h expected=%h",trap.pc,expected[1],trap.fault.kind,expected[6],trap.fault.address,expected[7]);
        if (trap.pc==TERMINAL_PC) begin
          if (events!=EXPECTED_EVENTS || wide==0 || stalls==0 || packet_stalls==0) $fatal(1,"Missing coverage/events");
          foreach (mem[i]) if (mem[i]!=expected_mem[i]) $fatal(1,"Memory mismatch byte %0d",i);
          $display("PASS core seed=%0d cycles=%0d events=%0d four-wide=%0d stalls=%0d",seed,cycles,events,wide,stalls);
          $display("pipeline stalls=%0d redirects with outstanding fetch=%0d",packet_stalls,stale_redirects);
          $finish;
        end
        resume_pending=1; saved_resume=trap.pc+4;
      end
      if (rv && rr) resume_pending=0;
      // Capture a request exactly once. Response payload stays held until ready.
      if (iqv && iqr) begin
        if (ia[3:0]!=0) $fatal(1,"Unaligned IF block");
        for (int i=0;i<4;i++) begin
          ir.words[i]=(ia/4+32'(i)<PROGRAM_WORDS)?imem[ia/4+32'(i)]:32'h13;
          ir.access_error[i]=(ia+32'(4*i))==IF_ERROR_PC;
        end
        iw=2+(cycles+seed)%6;
      end else if (irv && irr) iw=-1;
      else if (iw>0) iw--;
      if (dqv && dqr) begin
        if (dq.aligned_address[1:0]!=0) $fatal(1,"Unaligned data port");
        dr='0;
        dr.error=dq.aligned_address>=4096;
        if (!dr.error) for (int i=0;i<4;i++) begin
          if (dq.write && dq.byte_mask[i]) mem[dq.aligned_address+32'(i)]=dq.write_data[8*i+:8];
          dr.read_data[8*i+:8]=mem[dq.aligned_address+32'(i)];
        end
        dw=3+(cycles+seed)%8;
      end else if (drv && drr) dw=-1;
      else if (dw>0) dw--;
      tick(); cycles++;
    end
    $fatal(1,"Timeout events=%0d",events);
  end
endmodule
